#!/usr/bin/env python"""song_feature_QC_visualiser.py   ·   v2025‑07‑17==============================================Visual QC for *detected* song intervals only( single yellow overlay, no amplitude / entropy panels ).JSON format required--------------------[  {    "file_name": "...wav",    "file_path": ".../path/to/file.wav",    "duration_seconds": 12.34,    "contains_song": true | false,    "detected_song_times": [[start, end], ...]   # seconds  },  ...]The script stacks spectrogram “rows” (default 10 s each),draws transparent yellow bands wherever `detected_song_times`fall, and places a dashed red line at every file boundary."""from __future__ import annotationsimport argparse, jsonfrom pathlib import Pathimport numpy as npimport matplotlib.pyplot as pltimport matplotlib.patches as mpatchesimport soundfile as sffrom scipy.signal import spectrogram# ───────── tunables ──────────ROW_DUR         = 10.0        # seconds per horizontal laneSPEC_NPERSEG    = 1024SPEC_NOVERLAP   = 512SPEC_VMIN, SPEC_VMAX = -90, -20   # dB colour‑range# ────────────────── helpers ──────────────────def _draw_segment(ax, audio, sr, offset, dur):    """Draw a greyscale spectrogram of `audio[0:dur]` at x‑offset `offset`."""    if dur <= 0:        return    f, t, S = spectrogram(        audio[: int(round(dur * sr))],        fs=sr, nperseg=SPEC_NPERSEG, noverlap=SPEC_NOVERLAP,        scaling="spectrum", mode="magnitude",    )    S_db = 20 * np.log10(S + 1e-12)    ax.pcolormesh(        offset + t, f, S_db,        shading="auto", cmap="gray_r",        vmin=SPEC_VMIN, vmax=SPEC_VMAX,    )def _highlight(ax, spans, pane_offset, seg_dur,               colour="yellow", alpha=0.45, zorder=5):    """Draw semi‑transparent rectangles for `spans` within a row slice."""    for s, e in spans:        if e <= 0 or s >= seg_dur:            continue        ax.axvspan(            pane_offset + max(s, 0),            pane_offset + min(e, seg_dur),            color=colour, alpha=alpha, zorder=zorder,        )def _save_legend(out_dir: Path):    """One‑off legend PNG so the QC panels themselves stay clean."""    fig, ax = plt.subplots(figsize=(3, 1.5))    ax.axis("off")    handles = [        mpatches.Patch(color="yellow", alpha=0.45,                       label="Detected song"),        plt.Line2D([0], [0], color="red", ls="--", lw=2,                   label="File boundary"),    ]    ax.legend(handles=handles, frameon=False, loc="center")    fig.savefig(out_dir / "QC_key.png", dpi=300, bbox_inches="tight")    plt.close(fig)    print(f"[INFO] Saved {(out_dir/'QC_key.png').resolve()}")# ────────────────── core engine ──────────────────def build_QC_panels(json_path: str | Path,                    output_dir: str | Path,                    *,                    sr: int = 44_100,                    rows_per_fig: int = 6):    json_path  = Path(json_path)    output_dir = Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    with json_path.open() as f:        recs_all = json.load(f)    # Keep only recordings that actually have song spans    recs = [r for r in recs_all if r["detected_song_times"]]    if not recs:        print("[WARN] Nothing to plot – no detected_song_times found.")        return    rec_idx, rec_progress, fig_no = 0, 0.0, 1    legend_done = False    while rec_idx < len(recs):        fig, axes = plt.subplots(            rows_per_fig, 1,            figsize=(10, 2 * rows_per_fig),            sharex=True, constrained_layout=True,        )        axes = np.atleast_1d(axes)        for ax in axes:            if rec_idx >= len(recs):                ax.axis("off")                continue            offset, titles = 0.0, []            while offset < ROW_DUR and rec_idx < len(recs):                rec      = recs[rec_idx]                wav_path = Path(rec["file_path"])                # ─── lazy‑load WAV once per recording ───                if rec_progress == 0.0:                    audio_full, sr_file = sf.read(wav_path)                    if audio_full.ndim > 1:                        audio_full = audio_full.mean(axis=1)                    if sr_file != sr:                        print(f"[WARN] {wav_path.name}: "                              f"sr {sr_file} ≠ {sr}; using {sr_file}")                        sr = sr_file                remaining = rec["duration_seconds"] - rec_progress                seg_dur   = min(remaining, ROW_DUR - offset)                # slice audio for this row fragment                start_idx = int(round(rec_progress * sr))                seg_audio = audio_full[                    start_idx : start_idx + int(round(seg_dur * sr))                ]                _draw_segment(ax, seg_audio, sr, offset, seg_dur)                # overlay yellow spans                shift = rec_progress                shifted_spans = [                    (s - shift, e - shift) for s, e in rec["detected_song_times"]                ]                _highlight(ax, shifted_spans, offset, seg_dur)                # advance cursors                rec_progress += seg_dur                offset       += seg_dur                finished = abs(rec_progress - rec["duration_seconds"]) < 1e-6                if finished:                    ax.axvline(offset, color="red", ls="--", lw=1.0, zorder=6)                    titles.append(wav_path.name)                    rec_idx     += 1                    rec_progress = 0.0            # aesthetics            ax.set_xlim(0, ROW_DUR)            ax.set_ylim(0, 10_000)            ax.set_yticks([0, 2500, 5000, 7500, 10_000])            ax.set_ylabel("Freq [Hz]")            ax.tick_params(labelsize=8)            if titles:                ax.set_title(" + ".join(titles), fontsize=9, pad=4)        axes[-1].set_xlabel("Time [s]")        fig.suptitle(f"Detected‑song QC panel {fig_no}", fontsize=12)        out_png = output_dir / f"song_QC_panel_{fig_no:03d}.png"        fig.savefig(out_png, dpi=300)        plt.close(fig)        print(f"[INFO] Saved {out_png.resolve()}")        if not legend_done:            _save_legend(output_dir)            legend_done = True        fig_no += 1# ────────────────── CLI entrypoint ──────────────────if __name__ == "__main__":    ap = argparse.ArgumentParser(        description="Visual QC for detected_song_times JSON."    )    ap.add_argument("--json_path",  required=True, type=Path)    ap.add_argument("--output_dir", required=True, type=Path)    ap.add_argument("--sr",         default=44_100, type=int,                    help="Expected sample rate (overridden if WAV differs).")    ap.add_argument("--rows",       default=6, type=int, dest="rows_per_fig",                    help="Spectrogram rows per PNG.")    args = ap.parse_args()    build_QC_panels(        args.json_path,        args.output_dir,        sr=args.sr,        rows_per_fig=args.rows_per_fig,    )#json_path = "/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/USA5510_unsegmented_songs/55_subsample_detected_song_intervals.json"#output_dir = "/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/USA5510_unsegmented_songs/55_subsample_detected_song_qc_panels"#build_QC_panels(json_path, output_dir,sr=44100,rows_per_fig=6)